#pragma once

#include <cstdint>
#include <qstring.h>

#define ENUM2IDX(item)		(static_cast<int>(item))

enum class IconIdx
    : uint8_t
{
    LOADCSV = 0,
    LOADFOLDER,
    CLEAR,
    FFT,
    EXPR,
};

///< How the icon source data is stored
enum class IconSource
    : uint8_t
{
    BASE64,   ///< inline base64-encoded data URI → retrieved from g_iconBase64[]
    SVG_FILE, ///< external .svg file → path stored in IconResource::path
};

///< Icon resource descriptor — binds identifier, human name, source type, and optional file path
struct IconResource
{
    IconIdx     id;
    const char* name;
    IconSource  source;
    const char* path;   ///< file path when source==SVG_FILE, nullptr / unused for BASE64
};

///< Icons in base64 format (defaults to 0x222222 colors)
static const QString g_iconBase64[] =
{
    // LOADCSV
    "data:image/svg+xml;base64,",

    // LOADFOLDER
    "data:image/svg+xml;base64,",

    // CLEAR
    "data:image/svg+xml;base64,",

    // FFT
    "data:image/svg+xml;base64,",

    // EXPR
    "data:image/svg+xml;base64,"
};

///< Master resource table — maps every IconIdx to its metadata and data source.
///< To switch an icon from embedded base64 to an external SVG file,
///< change its .source to IconSource::SVG_FILE and .path to the file path.
static const IconResource g_iconResources[] =
{
    { IconIdx::LOADCSV,    "LOADCSV",    IconSource::BASE64,   nullptr },
    { IconIdx::LOADFOLDER, "LOADFOLDER", IconSource::BASE64,   nullptr },
    { IconIdx::CLEAR,      "CLEAR",      IconSource::BASE64,   nullptr },
    { IconIdx::FFT,        "FFT",        IconSource::BASE64,   nullptr },
    { IconIdx::EXPR,       "EXPR",       IconSource::BASE64,   nullptr },
};

///< Look up an IconResource by IconIdx.  Returns nullptr when not found.
inline const IconResource* findIconResource(IconIdx id)
{
    for (const auto& res : g_iconResources)
    {
        if (res.id == id)
            return &res;
    }
    return nullptr;
}